import copy
from threading import Lock
from typing import Dict, Iterable, List, Optional, Protocol, Set

from .metrics_core import Metric

# Public sample name and metric family name of the target metadata metric.
# They are spelled out here because target_info is not collected from a
# registered collector but generated by the registry itself.
TARGET_INFO_SAMPLE = 'target_info'
TARGET_INFO_FAMILY = 'target'


class Collector(Protocol):
    def collect(self) -> Iterable[Metric]:
        """Collect metrics."""


class _EmptyCollector:
    def collect(self) -> Iterable[Metric]:
        return []


class DuplicateTimeseries(ValueError):
    def __init__(self, duplicates: Set[str]):
        msg = 'Duplicated timeseries in CollectorRegistry: {}'.format(
            duplicates)
        super().__init__(msg)
        self.duplicates: Set[str] = duplicates


class CollectorRegistry:
    """Metric collector registry.

    Collectors must have a no-argument method 'collect' that returns a list of
    Metric objects. The returned metrics should be consistent with the Prometheus
    exposition formats.
    """

    def __init__(self, auto_describe: bool = False, target_info: Optional[Dict[str, str]] = None,
                 support_collectors_without_names: bool = False):
        self._collector_to_names: Dict[Collector, List[str]] = {}
        self._names_to_collectors: Dict[str, Collector] = {}
        self._auto_describe = auto_describe
        self._lock = Lock()
        self._target_info: Optional[Dict[str, str]] = {}
        self._support_collectors_without_names = support_collectors_without_names
        self._collectors_without_names: List[Collector] = []
        self.set_target_info(target_info)

    def register(self, collector: Collector) -> None:
        """Add a collector to the registry."""
        with self._lock:
            names = self._get_names(collector)
            duplicates = set(self._names_to_collectors).intersection(names)
            if duplicates:
                raise DuplicateTimeseries(duplicates)
            for name in names:
                self._names_to_collectors[name] = collector
            self._collector_to_names[collector] = names
            if self._support_collectors_without_names and not names:
                self._collectors_without_names.append(collector)

    def unregister(self, collector: Collector) -> None:
        """Remove a collector from the registry."""
        with self._lock:
            for name in self._collector_to_names[collector]:
                del self._names_to_collectors[name]
            del self._collector_to_names[collector]
            if collector in self._collectors_without_names:
                self._collectors_without_names.remove(collector)

    def _get_names(self, collector):
        """Get names of timeseries the collector produces and clashes with."""
        desc_func = None
        # If there's a describe function, use it.
        try:
            desc_func = collector.describe
        except AttributeError:
            pass
        # Otherwise, if auto describe is enabled use the collect function.
        if not desc_func and self._auto_describe:
            desc_func = collector.collect

        if not desc_func:
            return []

        result = []
        type_suffixes = {
            'counter': ['_total', '_created'],
            'summary': ['_sum', '_count', '_created'],
            'histogram': ['_bucket', '_sum', '_count', '_created'],
            'gaugehistogram': ['_bucket', '_gsum', '_gcount'],
            'info': ['_info'],
        }
        for metric in desc_func():
            result.append(metric.name)
            for suffix in type_suffixes.get(metric.type, []):
                result.append(metric.name + suffix)
        return result

    def collect(self) -> Iterable[Metric]:
        """Yields metrics from the collectors in the registry."""
        collectors = None
        ti = None
        with self._lock:
            collectors = copy.copy(self._collector_to_names)
            if self._target_info:
                ti = self._target_info_metric()
        if ti:
            yield ti
        for collector in collectors:
            yield from collector.collect()

    def restricted_registry(self, names: Iterable[str] = (), *,
                            families: Iterable[str] = ()) -> "RestrictedRegistry":
        """Returns object that only collects some metrics.

        Two selection modes are declared separately:

        * ``names`` selects individual public sample names, e.g.
          ``'a_timeseries_sum'``. Only samples whose own name matches exactly
          are kept; a name is never treated as a prefix of another name.
        * ``families`` selects whole metric families by family name, e.g.
          ``'a_histogram'``. Every sample the family currently exposes is
          kept, so a composite family such as a Histogram stays complete and
          interpretable together with its HELP/TYPE/UNIT metadata.

        A family from which no sample is selected is dropped entirely rather
        than being emitted as metadata without samples. ``target_info`` is
        accepted only when its public sample name (``'target_info'``) is given
        as a sample selector or its family name (``'target'``) is given as a
        family selector, and only while target info is set.

        Each collector is executed at most once per collect(), no matter how
        many selectors resolve to it.

        Intended usage is:
            generate_latest(REGISTRY.restricted_registry(['a_timeseries']), escaping)
            generate_latest(REGISTRY.restricted_registry(families=['a_histogram']))

        Experimental."""
        return RestrictedRegistry(names, self, families=families)

    def set_target_info(self, labels: Optional[Dict[str, str]]) -> None:
        with self._lock:
            if labels:
                if not self._target_info and TARGET_INFO_SAMPLE in self._names_to_collectors:
                    raise ValueError('CollectorRegistry already contains a target_info metric')
                self._names_to_collectors[TARGET_INFO_SAMPLE] = _EmptyCollector()
            elif self._target_info:
                self._names_to_collectors.pop(TARGET_INFO_SAMPLE, None)
            self._target_info = labels

    def get_target_info(self) -> Optional[Dict[str, str]]:
        with self._lock:
            return self._target_info

    def _target_info_metric(self):
        m = Metric('target', 'Target metadata', 'info')
        m.add_sample('target_info', self._target_info, 1)
        return m

    def get_sample_value(self, name: str, labels: Optional[Dict[str, str]] = None) -> Optional[float]:
        """Returns the sample value, or None if not found.

        This is inefficient, and intended only for use in unittests.
        """
        if labels is None:
            labels = {}
        for metric in self.collect():
            for s in metric.samples:
                if s.name == name and s.labels == labels:
                    return s.value
        return None


class RestrictedRegistry:
    """A read-only view of a registry limited by explicit selectors.

    Sample selectors (``names``) are matched against the exact public sample
    name of every sample. Family selectors (``families``) are matched against
    the metric family name and keep every sample the family exposes, so
    composite metrics such as a Histogram remain complete and interpretable.
    Both are resolved by the same rules for the text and OpenMetrics
    encoders, because both consume the same restricted Metric objects.
    """

    def __init__(self, names: Iterable[str], registry: CollectorRegistry, *,
                 families: Iterable[str] = ()):
        self._name_set = frozenset(names)
        self._family_set = frozenset(families)
        self._registry = registry

    def collect(self) -> Iterable[Metric]:
        registry = self._registry
        target_info_metric = None
        with registry._lock:
            # Resolve every selector against the names the registry actually
            # published, so an unknown or merely similar name never pulls in
            # a collector. Sample selectors match public sample names and
            # family selectors match family names; both land on the same
            # collector object, which can therefore only be selected once.
            selected: Set[Collector] = set()
            for selector in self._name_set | self._family_set:
                collector = registry._names_to_collectors.get(selector)
                # The target_info placeholder is registry bookkeeping with
                # no samples; target info is handled by its own rule below.
                if collector is not None and not isinstance(collector, _EmptyCollector):
                    selected.add(collector)
            # Collectors registered without any names are always collected in
            # a restricted view, as they cannot be addressed by selector.
            selected.update(registry._collectors_without_names)
            # Keep registry order so a restricted scrape mirrors the full one.
            collectors = [c for c in registry._collector_to_names if c in selected]
            # Declared target_info acceptance rule, independent of the
            # generic lookup. The metadata family is exposed only when the
            # caller selected its public sample name as a sample selector
            # ('target_info'), or its family name as a family selector
            # ('target'), and only while target info is actually set. The two
            # modes stay distinct: a sample selector never names a family and
            # a family selector never names a sample.
            if registry._target_info and (
                    TARGET_INFO_SAMPLE in self._name_set
                    or TARGET_INFO_FAMILY in self._family_set):
                target_info_metric = registry._target_info_metric()
        if target_info_metric is not None:
            yield target_info_metric
        for collector in collectors:
            for metric in collector.collect():
                m = metric._restricted_metric(self._name_set, self._family_set)
                if m:
                    yield m


REGISTRY = CollectorRegistry(auto_describe=True)
